lld.referenceMermaid:
classDiagram
  class User {
    -String id
    -String name
  }
  class Group {
    -String id
    -List~User~ members
  }
  class Expense {
    -String id
    -User payer
    -Money total
    -List~Split~ splits
    -Instant createdAt
  }
  class Split {
    -User user
    -Money share
  }
  class Money {
    -long minorUnits
    -String currency
    +plus(Money m) Money
    +minus(Money m) Money
  }
  class SplitStrategy {
    <<interface>>
    +compute(Money total, List~SplitInput~ in) List~Split~
    +validate(Money total, List~SplitInput~ in) void
  }
  class EqualSplit
  class ExactSplit
  class PercentSplit
  class ExpenseService {
    +addExpense(ExpenseRequest r) Expense
    +settle(String groupId, User from, User to, Money m) Settlement
    +simplify(String groupId) List~Transfer~
  }
  class BalanceSheet {
    -Map netBalances
    +apply(Expense e) void
    +apply(Settlement s) void
  }
  class Settlement {
    -User from
    -User to
    -Money amount
  }
  Group "1" o-- "many" User
  Group "1" *-- "1" BalanceSheet
  Group "1" *-- "many" Expense
  Expense "1" *-- "many" Split
  Expense --> Money
  SplitStrategy <|.. EqualSplit
  SplitStrategy <|.. ExactSplit
  SplitStrategy <|.. PercentSplit
  ExpenseService --> SplitStrategy
  ExpenseService --> BalanceSheet
  BalanceSheet ..> Settlement

classDiagram
  class Theatre {
    -String id
    -String city
  }
  class Screen {
    -String id
    -SeatLayout layout
  }
  class Seat {
    -String id
    -String row
    -int number
    -SeatCategory category
  }
  class Show {
    -String id
    -Movie movie
    -Instant startTime
    -PricingPolicy pricing
  }
  class ShowSeat {
    -SeatStatus status
    -String holdId
    -Instant holdExpiresAt
    -long version
  }
  class Booking {
    -String id
    -BookingStatus status
    -Money amount
    +confirm(String paymentRef) void
    +expire() void
    +cancel() void
  }
  class HoldService {
    +hold(String showId, List~String~ seatIds, String userId) SeatHold
    +release(String holdId) void
  }
  class BookingService {
    +startBooking(SeatHold h) Booking
    +onPaymentResult(PaymentEvent e) void
  }
  class PricingPolicy {
    <<interface>>
    +price(Show s, Seat seat) Money
  }
  class HoldExpiryJob {
    +run() void
  }
  Theatre "1" *-- "many" Screen
  Screen "1" *-- "many" Seat
  Show --> Screen
  Show "1" *-- "many" ShowSeat
  ShowSeat --> Seat
  Booking "1" --> "many" ShowSeat
  BookingService --> HoldService
  BookingService --> Booking
  Show --> PricingPolicy
  HoldExpiryJob --> HoldService

classDiagram
  class Title {
    -String isbn
    -String name
    -List~String~ authors
  }
  class Copy {
    -String barcode
    -String branchId
    -CopyStatus status
  }
  class Member {
    -String id
    -MembershipPlan plan
  }
  class MembershipPlan {
    -int maxLoans
    -int loanDays
    -FinePolicy finePolicy
  }
  class Loan {
    -Copy copy
    -Member member
    -LocalDate dueAt
    -LocalDate returnedAt
  }
  class Hold {
    -Title title
    -Member member
    -HoldStatus status
    -LocalDate readyUntil
  }
  class FinePolicy {
    <<interface>>
    +fineFor(Loan l, LocalDate returned) Money
  }
  class DailyFinePolicy
  class CirculationService {
    +checkout(String memberId, String barcode) Loan
    +returnCopy(String barcode) void
  }
  class HoldService {
    +placeHold(String memberId, String isbn) Hold
    +onCopyReturned(Copy c) void
  }
  Title "1" *-- "many" Copy
  Member --> MembershipPlan
  MembershipPlan --> FinePolicy
  FinePolicy <|.. DailyFinePolicy
  Loan --> Copy
  Loan --> Member
  Hold --> Title
  Hold --> Member
  CirculationService ..> Loan
  CirculationService --> HoldService

classDiagram
  class Broker {
    -Map topics
    -ExecutorService executor
    +createTopic(String name, int partitions) Topic
    +publish(String topic, Message m) CompletableFuture
    +subscribe(String topic, String group, Handler h, SubscriptionOptions o) Subscription
    +close() void
  }
  class Topic {
    -String name
    -Partition[] partitions
    -Partitioner partitioner
  }
  class Partition {
    -List~Message~ log
    -long nextOffset
    +append(Message m) long
    +read(long offset, int max) List~Message~
  }
  class Message {
    -String id
    -String key
    -byte[] payload
    -Map headers
  }
  class ConsumerGroup {
    -String id
    -List~Subscription~ members
    -Map committedOffsets
    +rebalance() void
  }
  class Subscription {
    -Handler handler
    -SubscriptionOptions options
    +pause() void
    +close() void
  }
  class Dispatcher {
    +runPartition(ConsumerGroup g, Partition p) void
  }
  class Handler {
    <<interface>>
    +handle(Message m) void
  }
  class RetryPolicy {
    <<interface>>
    +nextDelay(int attempt) Optional
  }
  class Partitioner {
    <<interface>>
    +partition(Message m, int n) int
  }
  Broker "1" *-- "many" Topic
  Topic "1" *-- "many" Partition
  Partition "1" o-- "many" Message
  Topic --> Partitioner
  Broker "1" *-- "many" ConsumerGroup
  ConsumerGroup "1" o-- "many" Subscription
  Subscription --> Handler
  Dispatcher --> ConsumerGroup
  Dispatcher --> RetryPolicy
